// Polar sky plot: zenith at the centre, horizon at the outer circle, north at the top,
// azimuth increasing clockwise (east to the right).

export const PLANE_COLORS = ["#4e79a7", "#f28e2b", "#e15759", "#76b7b2", "#59a14f", "#edc948"];

export function drawSkyplot(canvas, snap) {
  const dpr = window.devicePixelRatio || 1;
  const size = canvas.clientWidth;
  canvas.width = canvas.height = Math.round(size * dpr);
  const ctx = canvas.getContext("2d");
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, size, size);

  const cx = size / 2, cy = size / 2, R = size / 2 - 22;
  const radius = (el) => R * (90 - el) / 90;               // elevation -> distance from centre
  const point = (az, el) => {
    const a = az * Math.PI / 180;
    return [cx + radius(el) * Math.sin(a), cy - radius(el) * Math.cos(a)];
  };

  ctx.strokeStyle = "#2a3441"; ctx.fillStyle = "#8b98a8"; ctx.lineWidth = 1;
  ctx.font = "11px system-ui, sans-serif"; ctx.textAlign = "center"; ctx.textBaseline = "middle";

  for (const el of [0, 30, 60]) {                           // elevation rings
    ctx.beginPath(); ctx.arc(cx, cy, radius(el), 0, 2 * Math.PI); ctx.stroke();
    if (el > 0) ctx.fillText(`${el}°`, cx + 10, cy - radius(el) + 8);
  }
  for (const az of [0, 90, 180, 270]) {                     // cardinal spokes
    const [x, y] = point(az, 0);
    ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(x, y); ctx.stroke();
  }
  const [nx, ny] = point(0, -8), [ex, ey] = point(90, -8), [sx, sy] = point(180, -8), [wx, wy] = point(270, -8);
  ctx.fillText("N", nx, ny); ctx.fillText("E", ex, ey); ctx.fillText("S", sx, sy); ctx.fillText("W", wx, wy);

  ctx.setLineDash([4, 4]); ctx.strokeStyle = "#4fc3f7";     // elevation mask
  ctx.beginPath(); ctx.arc(cx, cy, radius(snap.mask_deg), 0, 2 * Math.PI); ctx.stroke();
  ctx.setLineDash([]);

  ctx.textAlign = "left";
  snap.names.forEach((name, i) => {
    if (!snap.visible[i]) return;
    const [x, y] = point(snap.az[i], snap.el[i]);
    ctx.fillStyle = PLANE_COLORS[snap.planes[i]];
    ctx.beginPath(); ctx.arc(x, y, 6, 0, 2 * Math.PI); ctx.fill();
    ctx.fillStyle = "#dfe6ee"; ctx.fillText(name, x + 9, y);
  });
}

// 3D view (Three.js). Draws what Python computed; no orbital or DOP math happens here.
import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";
import { PLANE_COLORS } from "./skyplot.js";

const R_EARTH = 6378.137;      // km; scene units are Earth radii
const K = 1 / R_EARTH;

// Physical frame (x, y, z=north) -> Three.js frame (y is up): (x, y, z) -> (x, z, -y).
const toScene = (p) => new THREE.Vector3(p[0] * K, p[2] * K, -p[1] * K);

export function createGlobe(container, onPick) {
  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(45, 1, 0.01, 100);
  camera.position.set(6, 4, 9);

  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setPixelRatio(window.devicePixelRatio || 1);
  container.appendChild(renderer.domElement);

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enablePan = false;
  controls.minDistance = 1.6;
  controls.maxDistance = 20;

  scene.add(new THREE.AmbientLight(0xffffff, 0.8));
  const sun = new THREE.DirectionalLight(0xffffff, 1.2);
  sun.position.set(5, 3, 4);
  scene.add(sun);

  // Earth with a lat/lon graticule every 30 degrees (equator and prime meridian highlighted)
  const earth = new THREE.Mesh(
    new THREE.SphereGeometry(1, 64, 48),
    new THREE.MeshPhongMaterial({ color: 0x1b3550, shininess: 8 }));
  scene.add(earth);
  addGraticule(scene);

  // North pole marker so orientation is clear
  const pole = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 1.35, 0)]),
    new THREE.LineBasicMaterial({ color: 0xffffff }));
  scene.add(pole);

  // Receiver marker
  const receiver = new THREE.Mesh(
    new THREE.SphereGeometry(0.025, 16, 12), new THREE.MeshBasicMaterial({ color: 0xff3b30 }));
  scene.add(receiver);

  // Line-of-sight lines to visible satellites
  const losGeom = new THREE.BufferGeometry();
  losGeom.setAttribute("position", new THREE.BufferAttribute(new Float32Array(24 * 2 * 3), 3));
  const los = new THREE.LineSegments(losGeom, new THREE.LineBasicMaterial({ color: 0x7CFC9A, transparent: true, opacity: 0.6 }));
  scene.add(los);

  let sats = [];     // created on first update, once we know how many satellites there are

  function addRings(rings) {
    rings.forEach((pts, p) => {
      const line = new THREE.LineLoop(
        new THREE.BufferGeometry().setFromPoints(pts.map(toScene)),
        new THREE.LineBasicMaterial({ color: PLANE_COLORS[p], transparent: true, opacity: 0.35 }));
      scene.add(line);
    });
  }

  function update(snap) {
    if (sats.length === 0) {
      sats = snap.planes.map((plane) => {
        const m = new THREE.Mesh(new THREE.SphereGeometry(0.045, 16, 12),
          new THREE.MeshBasicMaterial({ color: PLANE_COLORS[plane], transparent: true }));
        scene.add(m);
        return m;
      });
    }
    const rx = toScene(snap.receiver);
    receiver.position.copy(rx);

    const buf = losGeom.attributes.position.array;
    let k = 0;
    snap.sat_positions.forEach((p, i) => {
      const pos = toScene(p);
      sats[i].position.copy(pos);
      const vis = snap.visible[i];
      sats[i].material.opacity = vis ? 1 : 0.25;
      sats[i].scale.setScalar(vis ? 1.3 : 0.8);
      if (vis) {
        buf.set([rx.x, rx.y, rx.z, pos.x, pos.y, pos.z], k);
        k += 6;
      }
    });
    losGeom.attributes.position.needsUpdate = true;
    losGeom.setDrawRange(0, k / 3);
  }

  // Click (not drag) on the Earth -> report latitude/longitude
  const ray = new THREE.Raycaster();
  let down = null;
  renderer.domElement.addEventListener("pointerdown", (e) => { down = [e.clientX, e.clientY]; });
  renderer.domElement.addEventListener("pointerup", (e) => {
    if (!down || Math.hypot(e.clientX - down[0], e.clientY - down[1]) > 4) return;
    const r = renderer.domElement.getBoundingClientRect();
    ray.setFromCamera(new THREE.Vector2(((e.clientX - r.left) / r.width) * 2 - 1,
                                        -((e.clientY - r.top) / r.height) * 2 + 1), camera);
    const hit = ray.intersectObject(earth)[0];
    if (!hit) return;
    // Inverse of toScene: scene (x, y, z) -> physical (x, -z, y)
    const x = hit.point.x, y = -hit.point.z, z = hit.point.y;
    onPick(Math.asin(z / hit.point.length()) * 180 / Math.PI, Math.atan2(y, x) * 180 / Math.PI);
  });

  function resize() {
    const w = container.clientWidth, h = container.clientHeight;
    renderer.setSize(w, h);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  }
  new ResizeObserver(resize).observe(container);
  resize();

  renderer.setAnimationLoop(() => { controls.update(); renderer.render(scene, camera); });

  return { update, addRings };
}

function addGraticule(scene) {
  const r = 1.002, N = 120;
  const material = (c) => new THREE.LineBasicMaterial({ color: c });
  for (let lat = -60; lat <= 60; lat += 30) {
    const pts = [];
    for (let i = 0; i <= N; i++) {
      const lon = (2 * Math.PI * i) / N, la = (lat * Math.PI) / 180;
      pts.push(toScene([r * R_EARTH * Math.cos(la) * Math.cos(lon), r * R_EARTH * Math.cos(la) * Math.sin(lon), r * R_EARTH * Math.sin(la)]));
    }
    scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), material(lat === 0 ? 0xf2c14e : 0x3b5878)));
  }
  for (let lon = 0; lon < 360; lon += 30) {
    const pts = [];
    for (let i = 0; i <= N; i++) {
      const la = (2 * Math.PI * i) / N, lo = (lon * Math.PI) / 180;
      pts.push(toScene([r * R_EARTH * Math.cos(la) * Math.cos(lo), r * R_EARTH * Math.cos(la) * Math.sin(lo), r * R_EARTH * Math.sin(la)]));
    }
    scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), material(lon === 0 ? 0xf2c14e : 0x3b5878)));
  }
}

// Glue: load Python (Pyodide), then on every change ask Python for the state of the sky
// and hand the result to the globe, the sky plot and the readout.
import { createGlobe } from "./skyplot.js" === undefined ? null : await import("./globe.js");
import { drawSkyplot, PLANE_COLORS } from "./skyplot.js";

const $ = (id) => document.getElementById(id);
const PY_FILES = ["__init__.py", "constellation.py", "geometry.py", "dop.py", "api.py"];
const DAY = 86400;

async function loadPython() {
  const pyodide = await loadPyodide();
  await pyodide.loadPackage("numpy");
  pyodide.FS.mkdir("/home/pyodide/sim");
  for (const f of PY_FILES) {
    const text = await (await fetch(`sim/${f}`)).text();
    pyodide.FS.writeFile(`/home/pyodide/sim/${f}`, text);
  }
  pyodide.runPython("import sys; sys.path.insert(0, '/home/pyodide')");
  return pyodide.pyimport("sim.api");
}

const fmt = (x, d = 2) => (x === null ? "–" : x.toFixed(d));

function hms(s) {
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = Math.floor(s % 60);
  return [h, m, sec].map((v) => String(v).padStart(2, "0")).join(":");
}

async function main() {
  const api = await loadPython();
  $("status").textContent = "Ready.";

  const globe = createGlobe($("globe"), (lat, lon) => {
    $("lat").value = lat.toFixed(2);
    $("lon").value = lon.toFixed(2);
    dirty = true;
  });
  globe.addRings(JSON.parse(api.orbit_rings()));

  let t = 0, playing = false, dirty = true, last = performance.now();

  function refresh() {
    const lat = Math.max(-90, Math.min(90, parseFloat($("lat").value)));
    const lon = parseFloat($("lon").value);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return;

    const snap = JSON.parse(api.snapshot(lat, lon, t));
    globe.update(snap);
    drawSkyplot($("sky"), snap);

    $("tlabel").textContent = `t = ${hms(t)} after start`;
    $("mask").textContent = snap.mask_deg;
    $("n").textContent = snap.n_visible;
    for (const k of ["gdop", "pdop", "hdop", "vdop", "tdop"]) $(k).textContent = fmt(snap.dop[k]);

    const rows = snap.names
      .map((name, i) => ({ name, az: snap.az[i], el: snap.el[i], vis: snap.visible[i], plane: snap.planes[i] }))
      .filter((s) => s.vis)
      .sort((a, b) => b.el - a.el);
    $("sats").tBodies[0].innerHTML = rows.map((s) =>
      `<tr><td><span class="dot" style="background:${PLANE_COLORS[s.plane]}"></span>${s.name}</td>` +
      `<td>${s.az.toFixed(1)}</td><td>${s.el.toFixed(1)}</td></tr>`).join("");
  }

  for (const id of ["lat", "lon"]) $(id).addEventListener("input", () => { dirty = true; });
  $("time").addEventListener("input", () => { t = parseFloat($("time").value) * 60; dirty = true; });
  $("play").addEventListener("click", () => {
    playing = !playing;
    $("play").textContent = playing ? "Pause" : "Play";
  });
  window.addEventListener("resize", () => { dirty = true; });

  function frame(now) {
    const dt = (now - last) / 1000;
    last = now;
    if (playing) {
      t = (t + dt * parseFloat($("speed").value)) % DAY;
      $("time").value = Math.floor(t / 60);
      dirty = true;
    }
    if (dirty) { dirty = false; refresh(); }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

main().catch((e) => { $("status").textContent = `Error: ${e.message}`; console.error(e); });

