import { loadPyodide } from "https://cdn.jsdelivr.net/pyodide/v0.26.4/full/pyodide.mjs";
import { loadSim } from "./pyloader.js";

let mc = null;
let currentRun = null;

const ready = loadSim(loadPyodide)
  .then((py) => { mc = py.pyimport("sim.montecarlo"); postMessage({ type: "ready" }); })
  .catch((e) => postMessage({ type: "error", message: String(e) }));

onmessage = async ({ data }) => {
  await ready;
  if (!mc) return;
  try {
    if (data.cmd === "start") {
      currentRun = data.runId;
      const info = JSON.parse(mc.mc_start(data.n, data.seed, data.pdopMax));
      postMessage({ type: "started", runId: data.runId, ...info });
    } else if (data.runId !== currentRun) {
      return;                                    // stale request from an older run
    } else if (data.cmd === "advance") {
      const adv = JSON.parse(mc.mc_advance(data.k, data.wantPoints));
      const summary = data.summaryDop ? JSON.parse(mc.mc_summary(data.summaryDop)) : null;
      postMessage({ type: "advanced", runId: data.runId, ...adv, summary });
    } else if (data.cmd === "summary") {
      postMessage({ type: "summary", runId: data.runId, summary: JSON.parse(mc.mc_summary(data.dopType)) });
    }
  } catch (e) {
    postMessage({ type: "error", message: String(e) });
  }
};

// Colour scale for Monte-Carlo trials (dark theme).
// Diverging around the PDOP threshold: teal (good) -> neutral at the threshold -> orange (bad).
// The scale runs from PDOP 1 to 2x the threshold and is clamped outside that range.
// Trials with fewer than 4 satellites (PDOP undefined) get their own violet.
const TEAL = [0x19, 0x9e, 0x70];
const NEUTRAL = [0xc3, 0xc2, 0xb7];
const ORANGE = [0xd9, 0x59, 0x26];
const UNDEFINED = [0x90, 0x85, 0xe9];
export const GRAY = [0x8b, 0x98, 0xa8];            // flashes fade to this and stay

const MIN_THRESHOLD = 1.1;                         // PDOP is never below ~1; keeps the scale well defined
const mix = (a, b, f) => a.map((v, i) => v + (b[i] - v) * f);
const css = (c) => `rgb(${c.map(Math.round).join(",")})`;

export const rgb01 = (c) => c.map((v) => v / 255);
export const cssColor = (c) => css(c);
export const UNDEFINED_RGB = UNDEFINED;

/** Colour (0-255 triple) for a trial with the given PDOP (null = undefined). */
export function trialColor(pdop, threshold) {
  if (pdop === null) return UNDEFINED;
  const thr = Math.max(threshold, MIN_THRESHOLD);
  const x = Math.min(Math.max(pdop, 1), 2 * thr);
  return x <= thr ? mix(TEAL, NEUTRAL, (x - 1) / (thr - 1)) : mix(NEUTRAL, ORANGE, (x - thr) / thr);
}

/** CSS gradient for the legend bar, with the neutral stop where PDOP = threshold. */
export function legendGradient(threshold) {
  const thr = Math.max(threshold, MIN_THRESHOLD);
  const mid = ((thr - 1) / (2 * thr - 1)) * 100;
  return `linear-gradient(to right, ${css(TEAL)}, ${css(NEUTRAL)} ${mid}%, ${css(ORANGE)})`;
}

// Hand-drawn canvas histogram. Bars are drawn with height proportional to count, so you can
// check any bar against the numbers in the results table.
const AXIS = "#8b98a8", GRID = "#2a3441", MARK = "#dfe6ee";

/**
 * spec = { bars: [{x0, x1, count, color}], xMin, xMax,
 *          ticks: [{x, label}], marker: {x, label} | null }
 */
export function drawBars(canvas, spec) {
  const dpr = window.devicePixelRatio || 1;
  const w = canvas.clientWidth, h = canvas.clientHeight;
  canvas.width = Math.round(w * dpr);
  canvas.height = Math.round(h * dpr);
  const ctx = canvas.getContext("2d");
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, w, h);

  const m = { l: 44, r: 8, t: 16, b: 22 };
  const plotW = w - m.l - m.r, plotH = h - m.t - m.b;
  const sx = (x) => m.l + ((x - spec.xMin) / (spec.xMax - spec.xMin)) * plotW;
  const yMax = Math.max(1, ...spec.bars.map((b) => b.count));
  const sy = (c) => m.t + plotH - (c / yMax) * plotH;

  ctx.font = "11px system-ui, sans-serif";
  ctx.lineWidth = 1;

  // recessive gridlines at 0, 50 %, 100 % of the tallest bar, labelled with counts
  ctx.textAlign = "right"; ctx.textBaseline = "middle";
  for (const f of [0, 0.5, 1]) {
    const y = sy(f * yMax);
    ctx.strokeStyle = f === 0 ? AXIS : GRID;
    ctx.beginPath(); ctx.moveTo(m.l, y); ctx.lineTo(w - m.r, y); ctx.stroke();
    ctx.fillStyle = AXIS;
    ctx.fillText(Math.round(f * yMax).toLocaleString(), m.l - 5, y);
  }

  for (const b of spec.bars) {
    const x0 = sx(b.x0) + 1, x1 = sx(b.x1) - 1;
    const top = sy(b.count);
    ctx.fillStyle = b.color;
    ctx.fillRect(x0, top, Math.max(1, x1 - x0), m.t + plotH - top);
  }

  ctx.textAlign = "center"; ctx.textBaseline = "top"; ctx.fillStyle = AXIS;
  for (const t of spec.ticks) ctx.fillText(t.label, sx(t.x), m.t + plotH + 5);

  if (spec.marker) {
    const x = sx(spec.marker.x);
    ctx.strokeStyle = MARK; ctx.setLineDash([4, 3]);
    ctx.beginPath(); ctx.moveTo(x, m.t - 4); ctx.lineTo(x, m.t + plotH); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = MARK; ctx.textBaseline = "bottom";
    ctx.textAlign = x > w - 90 ? "right" : "left";
    ctx.fillText(spec.marker.label, x + (x > w - 90 ? -4 : 4), m.t + 6);
  }
  canvas._hit = { bars: spec.bars, sx };
}

/** Index of the bar under a mouse event, or -1. */
export function barAt(canvas, clientX) {
  if (!canvas._hit) return -1;
  const x = clientX - canvas.getBoundingClientRect().left;
  const { bars, sx } = canvas._hit;
  return bars.findIndex((b) => x >= sx(b.x0) && x < sx(b.x1));
}

