  }

  function drawSatHistogram(s) {
    const counts = s.nsat.counts;
    const nz = counts.map((c, i) => (c > 0 ? i : -1)).filter((i) => i >= 0);
    const lo = Math.max(0, nz[0] - 1), hi = Math.min(counts.length - 1, nz[nz.length - 1] + 1);
