// and hand the result to the globe, the sky plot and the readout.
import { createGlobe } from "./globe.js";
import { drawSkyplot, PLANE_COLORS } from "./skyplot.js";

const $ = (id) => document.getElementById(id);
const PY_FILES = ["__init__.py", "constellation.py", "geometry.py", "dop.py", "api.py"];
const DAY = 86400;

async function loadPython() {
  const pyodide = await loadPyodide();
  await pyodide.loadPackage("numpy");
  pyodide.FS.mkdir("/home/pyodide/sim");
  for (const f of PY_FILES) {
    const text = await (await fetch(`sim/${f}`)).text();
    pyodide.FS.writeFile(`/home/pyodide/sim/${f}`, text);
  }
  pyodide.runPython("import sys; sys.path.insert(0, '/home/pyodide')");
  return pyodide.pyimport("sim.api");
}

const fmt = (x, d = 2) => (x === null ? "–" : x.toFixed(d));

function hms(s) {
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = Math.floor(s % 60);
  return [h, m, sec].map((v) => String(v).padStart(2, "0")).join(":");
}

