    const lat = Math.max(-90, Math.min(90, parseFloat($("lat").value)));
    const lon = parseFloat($("lon").value);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return;

    const snap = JSON.parse(api.snapshot(lat, lon, t));
    globe.update(snap);
