321	  }
322	  for (let lon = 0; lon < 360; lon += 30) {
323	    const pts = [];
324	    for (let i = 0; i <= N; i++) {
325	      const la = (2 * Math.PI * i) / N, lo = (lon * Math.PI) / 180;
326	      pts.push(toScene([r * R_EARTH * Math.cos(la) * Math.cos(lo), r * R_EARTH * Math.cos(la) * Math.sin(lo), r * R_EARTH * Math.sin(la)]));
327	    }
328	    scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), material(lon === 0 ? 0xf2c14e : 0x3b5878)));
329	  }

