"""Tiny Chrome DevTools Protocol client (standard library only) for testing the web app.

    with Browser() as b:
        b.open("http://127.0.0.1:8766/")
        b.wait("document.getElementById('status').textContent === 'Ready.'", 120)
        b.screenshot("/path/shot.png")
        print(b.errors)             # uncaught exceptions + console.error messages
"""
import base64, json, os, shutil, socket, struct, subprocess, tempfile, time, urllib.request


class WebSocket:
    def __init__(self, url):
        host, rest = url[len("ws://"):].split("/", 1)
        h, p = host.split(":")
        self.sock = socket.create_connection((h, int(p)), timeout=30)
        key = base64.b64encode(os.urandom(16)).decode()
        self.sock.sendall((f"GET /{rest} HTTP/1.1\r\nHost: {host}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
                           f"Sec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\n\r\n").encode())
        buf = b""
        while b"\r\n\r\n" not in buf:
            buf += self.sock.recv(1)
        assert b" 101 " in buf.split(b"\r\n")[0], buf

    def send(self, text):
        data = text.encode()
        n = len(data)
        head = b"\x81" + (bytes([0x80 | n]) if n < 126 else b"\xfe" + struct.pack(">H", n) if n < 65536 else b"\xff" + struct.pack(">Q", n))
        mask = os.urandom(4)
        self.sock.sendall(head + mask + bytes(b ^ mask[i % 4] for i, b in enumerate(data)))

    def _read(self, n):
        out = b""
        while len(out) < n:
            chunk = self.sock.recv(n - len(out))
            if not chunk:
                raise ConnectionError("socket closed")
            out += chunk
        return out

    def recv(self):
        message = b""
        while True:
            b0, b1 = self._read(2)
            op, n = b0 & 0x0F, b1 & 0x7F
            if n == 126: n = struct.unpack(">H", self._read(2))[0]
            elif n == 127: n = struct.unpack(">Q", self._read(8))[0]
            payload = self._read(n)
            if op == 8: raise ConnectionError("closed")
            if op == 9:
                self.sock.sendall(b"\x8a\x80" + os.urandom(4)); continue
            message += payload
            if b0 & 0x80:
                return message.decode()


class Browser:
    def __init__(self, port=9333, width=1400, height=900):
        self.port, self.errors, self.logs, self._id = port, [], [], 0
        self.profile = tempfile.mkdtemp()
        self.proc = subprocess.Popen(
            ["google-chrome", "--headless=new", "--no-sandbox", f"--remote-debugging-port={port}", f"--user-data-dir={self.profile}",
             "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist", f"--window-size={width},{height}",
             "--disable-extensions", "about:blank"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        for _ in range(100):
            try:
                tabs = json.load(urllib.request.urlopen(f"http://127.0.0.1:{port}/json"))
                page = [t for t in tabs if t["type"] == "page"][0]
                break
            except Exception:
                time.sleep(0.1)
        self.ws = WebSocket(page["webSocketDebuggerUrl"])
        for domain in ("Page", "Runtime", "Log"):
            self.call(f"{domain}.enable")

    def __enter__(self): return self
    def __exit__(self, *a):
        try: self.proc.terminate(); self.proc.wait(10)
        except Exception: self.proc.kill()
        shutil.rmtree(self.profile, ignore_errors=True)

    def _event(self, msg):
        m, p = msg["method"], msg["params"]
        if m == "Runtime.exceptionThrown":
            d = p["exceptionDetails"]
            self.errors.append("EXCEPTION: " + (d.get("exception", {}).get("description") or d.get("text", "")) + f" @ {d.get('url','')}:{d.get('lineNumber')}")
        elif m == "Runtime.consoleAPICalled":
            text = " ".join(str(a.get("value", a.get("description", ""))) for a in p["args"])
            self.logs.append(f"{p['type']}: {text}")
            if p["type"] in ("error", "assert"): self.errors.append("console.error: " + text)
        elif m == "Log.entryAdded" and p["entry"]["level"] == "error":
            self.errors.append("log: " + p["entry"]["text"] + " " + p["entry"].get("url", ""))

    def call(self, method, **params):
        self._id += 1
        self.ws.send(json.dumps({"id": self._id, "method": method, "params": params}))
        while True:
            msg = json.loads(self.ws.recv())
            if msg.get("id") == self._id:
                if "error" in msg: raise RuntimeError(f"{method}: {msg['error']}")
                return msg["result"]
            if "method" in msg: self._event(msg)

    def pump(self, seconds=0.2):
        """Process pending events for a short while."""
        self.ws.sock.settimeout(seconds)
        try:
            while True: self._event_or_ignore(json.loads(self.ws.recv()))
        except (socket.timeout, TimeoutError): pass
        finally: self.ws.sock.settimeout(60)

    def _event_or_ignore(self, msg):
        if "method" in msg: self._event(msg)

    def open(self, url): self.call("Page.navigate", url=url)

    def eval(self, expression):
        r = self.call("Runtime.evaluate", expression=expression, returnByValue=True, awaitPromise=True)
        if "exceptionDetails" in r:
            d = r["exceptionDetails"]; raise RuntimeError("JS: " + (d.get("exception", {}).get("description") or d.get("text")))
        return r["result"].get("value")

    def wait(self, condition, timeout=60):
        end = time.time() + timeout
        while time.time() < end:
            self.pump(0.2)
            try:
                if self.eval(f"Boolean({condition})"): return True
            except RuntimeError: pass
            time.sleep(0.2)
        raise TimeoutError(f"timed out waiting for: {condition}\nstatus text: {self.eval('document.body.innerText.slice(0,400)')}\nerrors: {self.errors[:5]}")

    def screenshot(self, path):
        data = self.call("Page.captureScreenshot", format="png")["data"]
        open(path, "wb").write(base64.b64decode(data))

