1	// The constellation: which satellites exist, which are switched on, and the Constellation tab
2	// that edits them. The numbers (orbits, validation, ring paths) come from Python (sim/api.py);
3	// this file keeps the list, the colours and the labels, and draws the controls.
4	
5	const $ = (id) => document.getElementById(id);
6	
7	const MAX_SATELLITES = 300;                      // same limit as sim/api.py
8	const SYSTEM_COLORS = { gps: "#3987e5", galileo: "#eda100", beidou: "#d55181" };
9	// colours for satellites you add (one per added group), chosen by eye to differ from the three above
10	const CUSTOM_COLORS = ["#e66767", "#9ccc65", "#b39ddb", "#ffb74d"];
11	
12	const nf = (x, d = 0) => x.toLocaleString(undefined, { minimumFractionDigits: d, maximumFractionDigits: d });
13	const hm = (s) => `${Math.floor(s / 3600)} h ${Math.round((s % 3600) / 60)} min`;
14	const escapeHtml = (s) => s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
15	
16	/**
17	 * hooks.globe: the globe (setConstellation); hooks.onChange(): called after every change.
18	 * Returns the functions the rest of the page needs.
19	 */
20	export function initConstellation(api, hooks) {
21	  const presetList = JSON.parse(api.preset_info());
22	  let groups = [];                // {id, label, color, preset (key) | null}
23	  let sats = [];                  // {label, group (id), enabled, elements}
24	  let nextGroupId = 1, nextColor = 0, customCount = 0, walkerCount = 0, customGroupId = null;
25	  let locked = false;             // true while a Monte Carlo run is using the constellation: no changes
26	  const openGroups = new Set();
27	
28	  const groupOf = (s) => groups.find((g) => g.id === s.group);
29	  const colorOf = (s) => groupOf(s).color;
30	  const customColor = () => CUSTOM_COLORS[nextColor++ % CUSTOM_COLORS.length];
31	
32	  // ---- changing the constellation -----------------------------------------------------------
33	  function sync() {
34	    const info = JSON.parse(api.set_constellation(JSON.stringify(sats.map((s) => s.elements)),
35	                                                  JSON.stringify(sats.map((s) => s.enabled))));
36	    const firstOnRing = (r) => info.ring_of.indexOf(r);
37	    hooks.globe.setConstellation({
38	      colors: sats.map(colorOf),
39	      ringOf: info.ring_of,
40	      paths: info.paths,
41	      ringColors: info.paths.map((_, r) => colorOf(sats[firstOnRing(r)])),
42	      ringActive: info.paths.map((_, r) => sats.some((s, i) => info.ring_of[i] === r && s.enabled)),
43	    });
44	  }
45	
46	  function changed() {
47	    sync();
48	    render();
49	    hooks.onChange();
50	  }
51	
52	  function room(n) {
53	    if (sats.length + n > MAX_SATELLITES) throw new Error(`at most ${MAX_SATELLITES} satellites are allowed`);
54	  }
55	
56	  function addPreset(key) {
57	    if (locked || groups.some((g) => g.preset === key)) return;
58	    const info = presetList.find((p) => p.key === key);
59	    const data = JSON.parse(api.preset_elements(key));
60	    room(data.elements.length);
61	    const group = { id: nextGroupId++, label: info.label, color: SYSTEM_COLORS[info.system], preset: key };
62	    groups.push(group);
63	    data.elements.forEach((elements, i) => sats.push({ label: `${info.short}-${data.names[i]}`, group: group.id, enabled: true, elements }));
64	    changed();
65	  }
66	
67	  function removeGroup(id) {
68	    if (locked) return;
69	    groups = groups.filter((g) => g.id !== id);
70	    sats = sats.filter((s) => s.group !== id);
71	    if (id === customGroupId) customGroupId = null;
72	    changed();
73	  }
74	
75	  function addCustomSatellite(elements) {
76	    if (locked) return "";
77	    room(1);
78	    if (customGroupId === null || !groups.some((g) => g.id === customGroupId)) {
79	      customGroupId = nextGroupId++;
80	      groups.push({ id: customGroupId, label: "Added satellites", color: customColor(), preset: null });
81	    }
82	    customCount += 1;
83	    sats.push({ label: `X${customCount}`, group: customGroupId, enabled: true, elements });
84	    changed();
85	    return `X${customCount}`;
86	  }
87	
88	  function addWalker(T, P, F, data) {
89	    if (locked) return;
90	    room(data.elements.length);
91	    walkerCount += 1;
92	    const group = { id: nextGroupId++, label: `Walker ${T}/${P}/${F} (#${walkerCount})`, color: customColor(), preset: null };
93	    groups.push(group);
94	    data.elements.forEach((elements, i) => sats.push({ label: `W${walkerCount}-${data.names[i]}`, group: group.id, enabled: true, elements }));
95	    changed();
96	  }
97	
98	  function toggleSat(i) {
99	    if (!locked && sats[i]) { sats[i].enabled = !sats[i].enabled; changed(); }
100	  }
101	
102	  function setGroupEnabled(id, on) {
103	    if (locked) return;
104	    sats.forEach((s) => { if (s.group === id) s.enabled = on; });
105	    changed();
106	  }
107	
108	  function deleteSat(i) {
109	    if (locked) return;
110	    const id = sats[i].group;
111	    sats.splice(i, 1);
112	    if (!sats.some((s) => s.group === id)) groups = groups.filter((g) => g.id !== id);
113	    changed();
114	  }
115	
116	  function reset() {
117	    if (locked) return;
118	    groups = []; sats = []; customGroupId = null; customCount = 0; walkerCount = 0; nextColor = 0;
119	    addPreset("gps");
120	  }
121	
122	  // ---- what the rest of the page asks for -------------------------------------------------------------
