    const r = JSON.parse(api.orbit_from_form(JSON.stringify(satelliteParams())));
    if (r.ok) {
      const i = r.info;
      message("cs-msg", i.ecc === 0
        ? `Circular orbit, altitude ${nf(i.perigee_alt_km)} km, period ${hm(i.period_s)}`
